import{_ as i,o as a,c as t,a3 as e}from"./chunks/framework.DeRSg1wr.js";const g=JSON.parse('{"title":"自动打印调用参数和时间","description":"启用 Web 与 Dubbo 的调用参数和耗时日志，了解默认行为与表单编码要求。","frontmatter":{"title":"自动打印调用参数和时间","date":"2022-09-12T15:53:01.000Z","permalink":"/pages/250a98/","description":"启用 Web 与 Dubbo 的调用参数和耗时日志，了解默认行为与表单编码要求。"},"headers":[],"relativePath":"pages/250a98/index.md","filePath":"10.文档/240.自动打印调用参数和时间.md"}'),n={name:"pages/250a98/index.md"};function l(p,s,h,k,r,o){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="自动打印调用参数和时间" tabindex="-1">自动打印调用参数和时间 <a class="header-anchor" href="#自动打印调用参数和时间" aria-label="Permalink to &quot;自动打印调用参数和时间&quot;">​</a></h1><p>开启后，TLog 在 Servlet Web 入口和 Dubbo/Dubbox 服务提供方打印每次调用的参数和耗时。WebFlux、Gateway 和 Dubbo 消费方没有这个功能。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tlog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enable-invoke-time-print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>默认值为 false，旧 <code>tlog.enableInvokeTimePrint</code> 写法仍可通过 Spring relaxed binding 绑定。该开关不等于为任意 HTTP 客户端、MQ 或所有方法自动测量耗时。</p><h2 id="输出内容" tabindex="-1">输出内容 <a class="header-anchor" href="#输出内容" aria-label="Permalink to &quot;输出内容&quot;">​</a></h2><p>Servlet 日志包含 URL、请求参数映射和耗时；Dubbo/Dubbox 日志包含接口、方法、调用参数和耗时。例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;0&gt;&lt;trace-example&gt; [TLOG]开始请求URL[/orders],参数为:{&quot;page&quot;:[&quot;1&quot;]}</span></span>
<span class="line"><span>&lt;0&gt;&lt;trace-example&gt; [TLOG]结束URL[/orders]的调用,耗时为:12毫秒</span></span></code></pre></div><p>以上仅说明格式，数值不是性能测试结果。Servlet 参数映射不等于完整 JSON body 或上传文件内容；TLog 不会为了这个开关自动复制任意请求体。</p><p>关闭开关时 TLog 不读取请求参数。Servlet 异步请求的耗时只覆盖过滤器的单次调用，不等于完整的异步业务耗时。</p><h2 id="普通-spring-配置" tabindex="-1">普通 Spring 配置 <a class="header-anchor" href="#普通-spring-配置" aria-label="Permalink to &quot;普通 Spring 配置&quot;">​</a></h2><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">bean</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tlogSpringAware&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.yomahub.tlog.spring.TLogSpringAware&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">bean</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.yomahub.tlog.spring.TLogPropertyInit&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> depends-on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tlogSpringAware&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">property</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;enableInvokeTimePrint&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">bean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>日志会包含业务参数。如果参数里可能有密码、身份证号等敏感数据，请评估后再开启。</p>`,12)])])}const E=i(n,[["render",l]]);export{g as __pageData,E as default};
